@namespace sv_c3c929fd44a14d0c896bb098e4ab2440.Components.Pages.Settings
@using sv_c3c929fd44a14d0c896bb098e4ab2440.Services

<div class="settings-section">
    <h2>Security</h2>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="two-factor-section">
        <h3>Two-Factor Authentication</h3>
        <label class="toggle-row">
            <span>
                Two-Factor Authentication
                @if (TwoFactorEnabled)
                {
                    <span class="status-badge enabled">Enabled</span>
                }
                else
                {
                    <span class="status-badge disabled">Disabled</span>
                }
            </span>
            <input type="checkbox" checked="@TwoFactorEnabled" disabled />
        </label>
        @if (LastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @LastPasswordChange.Value.ToString("f")</p>
        }
    </div>

    <ActiveSessionsTable Sessions="@Sessions"
                         CurrentSessionId="@CurrentSessionId"
                         OnRevoke="HandleRevoke" />
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<(string current, string newPass)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled => Settings?.TwoFactorEnabled ?? false;
    private DateTime? LastPasswordChange => Settings?.LastPasswordChange;
    private List<ActiveSession>? Sessions => Settings?.Sessions;

    private async Task HandleChangePassword((string current, string newPass) args)
    {
        await OnChangePassword.InvokeAsync(args);
    }

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
    }
}

