@namespace sv_c3c929fd44a14d0c896bb098e4ab2440.Components.Pages.Settings
@using sv_c3c929fd44a14d0c896bb098e4ab2440.Services

<div class="settings-section">
    <h2>Appearance</h2>

    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            <label>
                <input type="radio" name="theme" value="Light"
                       checked="@(Theme == "Light")" @onchange="@(() => Theme = "Light")" />
                Light
            </label>
            <label>
                <input type="radio" name="theme" value="Dark"
                       checked="@(Theme == "Dark")" @onchange="@(() => Theme = "Dark")" />
                Dark
            </label>
            <label>
                <input type="radio" name="theme" value="System"
                       checked="@(Theme == "System")" @onchange="@(() => Theme = "System")" />
                System
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            <label>
                <input type="radio" name="fontSize" value="Small"
                       checked="@(FontSize == "Small")" @onchange="@(() => FontSize = "Small")" />
                Small
            </label>
            <label>
                <input type="radio" name="fontSize" value="Medium"
                       checked="@(FontSize == "Medium")" @onchange="@(() => FontSize = "Medium")" />
                Medium
            </label>
            <label>
                <input type="radio" name="fontSize" value="Large"
                       checked="@(FontSize == "Large")" @onchange="@(() => FontSize = "Large")" />
                Large
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language">
            <option value="en">English</option>
            <option value="es">Spanish</option>
            <option value="fr">French</option>
            <option value="de">German</option>
            <option value="ja">Japanese</option>
            <option value="zh">Chinese</option>
        </select>
    </div>

    <div class="toggle-group">
        <label class="toggle-row">
            <span>Compact Mode</span>
            <input type="checkbox" @bind="CompactMode" />
        </label>
    </div>

    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <button class="btn btn-primary">Sample Button</button>
        <p class="preview-meta">
            Theme: @Theme | Font: @FontSize | Compact: @(CompactMode ? "On" : "Off")
        </p>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @(IsSaving ? "Saving..." : "Save")
        </button>
    </div>

    @if (ShowSuccessMessage)
    {
        <div class="toast success">Appearance settings saved!</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "System";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "en";
    private bool CompactMode { get; set; }
    private bool IsSaving { get; set; }
    private bool ShowSuccessMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private bool _initialized;

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{Theme.ToLowerInvariant()} preview-font-{FontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccessMessage = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        ShowSuccessMessage = false;
        StateHasChanged();
    }
}

